<fieldset class="rounded-xl border border-line bg-white p-6">
<div class="mb-4 flex justify-between"><h2 class="font-semibold">Line <span x-text="index+1"></span></h2><button type="button" @click="remove(index)" :disabled="lines.length===1" class="text-sm text-slate-500 disabled:opacity-30">Remove line</button></div>
<div class="grid gap-5 md:grid-cols-2">
@if($kind==='dispatch')
<input type="hidden" :name="`lines[${index}][processing_job_step_id]`" x-model="line.processing_job_step_id">
<label class="text-sm md:col-span-2">Released fabric in company storage
<select required :name="`lines[${index}][source_stock_position_id]`" x-model="line.source_stock_position_id" class="mt-1 block w-full rounded-lg border border-line p-2"><option value="">Choose matching stock</option><template x-for="c in choices" :key="c.id"><option :value="c.id" x-text="c.label+' / Available '+format(c.available)+' '+c.unit"></option></template></select></label>
<p x-show="choice(line).id" class="rounded-lg bg-slate-50 p-3 text-sm md:col-span-2"><span x-text="'Available: '+format(choice(line).available)+' '+(choice(line).unit||'')"></span><span x-show="choice(line).roll" class="mt-1 block font-medium">This is a tracked physical roll. Dispatch its entire remaining quantity. Splitting a roll before dispatch is not available yet.</span></p>
<label class="text-sm">Contractor custody location<select required :name="`lines[${index}][contractor_location_id]`" x-model="line.contractor_location_id" class="mt-1 block w-full rounded-lg border border-line p-2"><option value="">Choose assigned vendor storage</option>@foreach($contractorLocations as $l)<option value="{{ $l->id }}">{{ $l->warehouse->name }} / {{ $l->name }}</option>@endforeach</select></label>
<label class="text-sm">Dispatch quantity <span x-text="choice(line).unit"></span><input required type="number" :min="choice(line).roll ? choice(line).onHand : step(line)" :max="choice(line).available" :step="step(line)" :name="`lines[${index}][quantity]`" x-model="line.quantity" class="mt-1 block w-full rounded-lg border border-line p-2"><button type="button" x-show="choice(line).roll" @click="line.quantity=choice(line).onHand" class="mt-2 text-sm font-medium text-brand">Use full roll quantity</button></label>
@elseif($kind==='receipt')
<label class="text-sm md:col-span-2">Outstanding dispatch line<select required :name="`lines[${index}][processing_dispatch_line_id]`" x-model="line.processing_dispatch_line_id" class="mt-1 block w-full rounded-lg border border-line p-2"><option value="">Choose a dispatch line</option><template x-for="c in choices" :key="c.id"><option :value="c.id" x-text="c.label+' / Outstanding '+format(c.available)+' '+c.unit"></option></template></select></label>
<p x-show="choice(line).id" class="rounded-lg bg-slate-50 p-3 text-sm md:col-span-2"><span x-text="'Issued '+format(choice(line).issued)+' / Previously closed '+format(choice(line).closed)+' / Outstanding '+format(choice(line).available)+' '+(choice(line).unit||'')"></span><span class="mt-1 block" x-text="'Fabric: '+(choice(line).input||'')+' to '+(choice(line).output||'')+' / Saved rate PKR '+format(choice(line).rate,8)+' per '+(choice(line).billingUnit||'')"></span></p>
<label class="text-sm">What came back?<select :name="`lines[${index}][disposition]`" x-model="line.disposition" @change="rejection(line)" class="mt-1 block w-full rounded-lg border border-line p-2"><option value="accepted">Accepted processed fabric</option><option value="rejected">Rejected service: unchanged fabric returned</option></select></label>
<label class="text-sm">Receiving location<select required :name="`lines[${index}][receiving_location_id]`" x-model="line.receiving_location_id" class="mt-1 block w-full rounded-lg border border-line p-2"><option value="">Choose company storage</option>@foreach($locations->whereIn('location_type',['internal','quarantine']) as $l)<option value="{{ $l->id }}">{{ $l->warehouse->name }} / {{ $l->name }}</option>@endforeach</select></label>
@foreach(['source_quantity'=>'Issued quantity being closed','output_quantity'=>'Actual fabric returned','normal_loss_quantity'=>'Normal loss','abnormal_loss_quantity'=>'Abnormal loss'] as $field=>$label)
<label class="text-sm">{{ $label }} <span x-text="choice(line).unit"></span><input required type="number" :min="{{ in_array($field,['source_quantity','output_quantity']) ? 'step(line)' : '0' }}" :step="step(line)" @if($field==='source_quantity') :max="choice(line).available" @endif @if(in_array($field,['normal_loss_quantity','abnormal_loss_quantity'])) :readonly="line.disposition==='rejected'" @endif :name="`lines[${index}][{{ $field }}]`" x-model="line.{{ $field }}" class="mt-1 block w-full rounded-lg border border-line p-2 read-only:bg-slate-50"></label>
@endforeach
<div class="rounded-lg bg-slate-50 p-4 text-sm md:col-span-2"><p>Quantity check: issued quantity being closed = returned fabric + normal loss + abnormal loss.</p><p class="mt-2" x-text="format(preview(line).source)+' = '+format(preview(line).output)+' + '+format(preview(line).normal)+' + '+format(preview(line).abnormal)"></p><p class="mt-1" x-text="'Difference: '+format(preview(line).difference)+' / Left with vendor: '+format(preview(line).remaining)+' '+(choice(line).unit||'')"></p><p class="mt-1" x-text="'Allowed normal loss for this receipt: '+format(preview(line).allowance)+' '+(choice(line).unit||'')"></p></div>
<label x-show="choice(line).id && !choice(line).sameUnit && line.disposition==='accepted'" class="text-sm">Inspected service quantity <span x-text="choice(line).billingUnit"></span><input type="number" min="0.000001" step="0.000001" :required="choice(line).id && !choice(line).sameUnit && line.disposition==='accepted'" :disabled="choice(line).sameUnit || line.disposition==='rejected'" :name="`lines[${index}][accepted_service_quantity]`" x-model="line.accepted_service_quantity" class="mt-1 block w-full rounded-lg border border-line p-2"><span class="mt-1 block text-xs text-slate-500">For piece/set billing, count the service units and record inspection evidence above.</span></label>
@foreach(['lot_number'=>'New returned lot number','roll_number'=>'New returned roll number'] as $field=>$label)<label class="text-sm">{{ $label }}<input @if($field==='lot_number') required @endif :name="`lines[${index}][{{ $field }}]`" x-model="line.{{ $field }}" class="mt-1 block w-full rounded-lg border border-line p-2"><span class="mt-1 block text-xs text-slate-500">{{ $field==='lot_number' ? 'Use a new unique reference for the fabric received.' : 'Required when the returned item tracks individual rolls. Use a new roll number.' }}</span></label>@endforeach
<label class="text-sm">Returned stock quality<select :name="`lines[${index}][quality_status]`" x-model="line.quality_status" class="mt-1 block w-full rounded-lg border border-line p-2">@foreach(['pending','released','held','rejected'] as $quality)<option value="{{ $quality }}">{{ ucfirst($quality) }}</option>@endforeach</select><span class="mt-1 block text-xs text-slate-500">Pending stock needs quality release before the next dispatch.</span></label>
<p class="text-sm md:col-span-2" x-text="'Estimated processing charge: PKR '+format(amount(line),4)+' / '+format(preview(line).quantity)+' '+(choice(line).billingUnit||'')"></p>
@else
<label class="text-sm">Accepted receipt line<select required :name="`lines[${index}][processing_receipt_line_id]`" x-model="line.processing_receipt_line_id" class="mt-1 block w-full rounded-lg border border-line p-2"><option value="">Choose unbilled service</option><template x-for="c in choices" :key="c.id"><option :value="c.id" x-text="c.label+' / Unbilled '+format(c.available)+' '+c.unit+' / PKR '+format(c.rate,8)+' per '+c.unit"></option></template></select></label>
<label class="text-sm">Service quantity to bill <span x-text="choice(line).unit"></span><input required type="number" :min="step(line)" :max="choice(line).available" :step="step(line)" :name="`lines[${index}][quantity]`" x-model="line.quantity" class="mt-1 block w-full rounded-lg border border-line p-2"></label>
<p x-show="choice(line).id" class="rounded-lg bg-slate-50 p-3 text-sm md:col-span-2" x-text="'Accepted '+format(choice(line).accepted)+' / Already billed '+format(choice(line).billed)+' / Unbilled '+format(choice(line).available)+' '+(choice(line).unit||'')+' / Estimated amount: PKR '+format(amount(line),4)"></p>
@endif
<template x-for="warning in warnings(line)" :key="warning"><p class="text-sm text-amber-800 md:col-span-2" role="status" x-text="warning"></p></template>
</div></fieldset>
